function brandFor(deptKey, n, templateIndex){
  const brands=BRAND_SETS[deptKey]||[];
  return brands[(Math.floor(n/7)+templateIndex)%brands.length]||['GhanaCart',['Everyday']];
}
function brandModel(deptKey, brand, models, type, n){
  const m=models[Math.floor(n/11)%models.length];
  const t=type.toLowerCase();
  if(deptKey==='phones'){
    if(t.includes('smartphone')||t.includes('foldable')||t.includes('rugged')||t.includes('gaming smartphone')||t.includes('business smartphone')||t.includes('budget smartphone')) return `${brand} ${m}`;
    if(t.includes('tablet')) return `${brand} ${type}`;
    if(t.includes('smartwatch')||t.includes('fitness band')) return `${brand} ${type}`;
    if(t.includes('earbud')||t.includes('headphone')||t.includes('headset')||t.includes('speaker')) return `${brand} ${type}`;
    return `${brand} ${type}`;
  }
  if(deptKey==='electronics'){
    if(t.includes('tv')||t.includes('soundbar')||t.includes('home theater')||t.includes('bluetooth speaker')||t.includes('party speaker')||t.includes('headphone')||t.includes('earphone')||t.includes('earbud')||t.includes('microphone')||t.includes('amplifier')||t.includes('receiver')||t.includes('radio')||t.includes('audio')) return `${brand} ${m} ${type}`;
    if(t.includes('camera')||t.includes('lens')||t.includes('camcorder')||t.includes('tripod')||t.includes('gimbal')||t.includes('flash')) return `${brand} ${type}`;
    if(t.includes('laptop')||t.includes('desktop')||t.includes('monitor')||t.includes('keyboard')||t.includes('mouse')||t.includes('printer')||t.includes('scanner')) return `${brand} ${type}`;
    return `${brand} ${type}`;
  }
  if(deptKey==='home') return `${brand} ${m} ${type}`;
  return `${brand} ${m} ${type}`;
}

