const TOTAL_CATALOG=20000000+Object.values(DEPARTMENTS).reduce((sum,d)=>sum+d.templates.length*d.acc.length,0);
function hash(n){let x=Math.sin(n*12.9898)*43758.5453;return x-Math.floor(x)}
function money(n){return `GH₵${n.toLocaleString('en-GH',{minimumFractionDigits:2,maximumFractionDigits:2})}`}
function catalogSize(){return TOTAL_CATALOG}
function getProduct(id){const n=Math.max(1,Number(id)||1);const keys=Object.keys(DEPARTMENTS);const departmentKey=keys[(n-1)%keys.length];const dept=DEPARTMENTS[departmentKey];const templateIndex=Math.floor(n/keys.length)%dept.templates.length;const t=dept.templates[templateIndex];const acc=dept.acc[Math.floor(n/(keys.length*dept.templates.length))%dept.acc.length];const color=COLORS[Math.floor(n/17)%COLORS.length];const size=SIZES[Math.floor(n/31)%SIZES.length];const mat=MATERIALS[Math.floor(n/47)%MATERIALS.length];const feat=FEATURES[Math.floor(n/61)%FEATURES.length];const brandData=brandFor(departmentKey,n,templateIndex);const brand=brandData[0];const model=brandModel(departmentKey,brand,brandData[1],t,n);const base=Math.max(5,Math.round((dept.base+Math.round(hash(n)*dept.base*18))*0.93*100)/100);const discount=(n%7===0||n%13===0)?(10+(n%31)):0;const price=Math.max(5,Math.round(base*(1-discount/100)*100)/100);const old=discount?Math.round(base*100)/100:null;const free=n%4===0;const stock=3+(n%180);const name=`${model} ${color} ${size}`;const imageName=`assets/images/products/${departmentKey}-${slug(t)}.svg`;return {id:n,departmentKey,department:dept.name,type:t,name,brand,model,short:`${brand} ${model} · ${size} · ${color} · ${feat}.`,description:`${brand} ${model} ${t.toLowerCase()} designed for everyday use. Built with ${mat}, featuring ${feat} performance. Recommended accessory: ${acc}.`,price,old,discount,freeShipping:free,stock,color,size,material:mat,feature:feat,accessory:acc,imageName,deliveryDays:2+(n%6)} }
function slug(s){return s.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
const IMAGE_KEYWORDS={};
function imageUrl(product){return `assets/images/products/${product.departmentKey}-${slug(product.type||'product')}.svg`}
function imagePlaceholder(product,large=false){const src=imageUrl(product);return `<div class="pic ${large?'bigpic':''}"><img src="${src}" alt="${escapeHtml(product.name)}" title="${escapeHtml(product.name)}" loading="lazy"></div>`}
function escapeHtml(s){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function productCard(p){return `<article class="card"><a href="product.html?id=${p.id}">${imagePlaceholder(p)} </a><button class="wish" onclick="toggleFavorite(${p.id});event.preventDefault()">♡</button><div class="cardbody"><a href="product.html?id=${p.id}"><div class="title">${escapeHtml(p.name)}</div><div class="meta">${escapeHtml(p.feature)} · ${p.stock} left</div><div><span class="price">${money(p.price)}</span>${p.old?`<span class="old">${money(p.old)}</span>`:''}</div>${p.discount?`<span class="tag orange">-${p.discount}% OFF</span>`:''}${p.freeShipping?` <span class="tag">FREE SHIPPING</span>`:''}</a><div class="actions"><a class="btn primary full" href="product.html?id=${p.id}">View item</a></div></div></article>`}
function searchProducts(q,page=1,limit=20){q=(q||'').trim().toLowerCase();const start=(page-1)*limit;const K=Object.keys(DEPARTMENTS).length;const candidates=[];if(!q){for(let i=1;i<=start+limit;i++)candidates.push(i)}else{Object.entries(DEPARTMENTS).forEach(([key,d],k)=>{const deptHit=d.name.toLowerCase().includes(q)||key.includes(q);d.templates.forEach((t,ti)=>{if(deptHit||t.toLowerCase().includes(q))for(let ai=0;ai<Math.min(d.acc.length,8);ai++)candidates.push(1+k+K*(ti+d.templates.length*ai))});d.acc.forEach((a,ai)=>{if(a.toLowerCase().includes(q))for(let ti=0;ti<Math.min(d.templates.length,8);ti++)candidates.push(1+k+K*(ti+d.templates.length*ai))})});const words=q.split(/\s+/);for(let i=1;i<=Math.min(250000,20000000)&&candidates.length<start+limit+1000;i++){const p=getProduct(i);if(words.every(w=>`${p.name} ${p.department} ${p.feature} ${p.accessory}`.toLowerCase().includes(w)))candidates.push(i)}}const seen=new Set(),out=[];for(const id of candidates){if(seen.has(id))continue;seen.add(id);const p=getProduct(id);if(!q||`${p.name} ${p.department} ${p.feature} ${p.accessory}`.toLowerCase().includes(q))out.push(p);if(out.length>=start+limit)break}return out.slice(start,start+limit)}
window.GhanaCart={DEPARTMENTS,REGIONS,TOTAL_CATALOG,getProduct,productCard,searchProducts,money,slug,escapeHtml,imagePlaceholder,imageUrl,catalogSize};
